ns16:scriptTask.ns16:script:
if (tw.local.idcRequest.parentRequestNo == "" || tw.local.idcRequest.parentRequestNo == null || tw.local.idcRequest.parentRequestNo == undefined ) {
	tw.local.cancelPath = tw.local.idcRequest.CustomerInfo.cif+"/DC Outward/"+tw.local.idcRequest.appInfo.instanceID+"ODC"+"/Canceled Cases";
}else{
	tw.local.cancelPath = tw.local.idcRequest.CustomerInfo.cif+"/DC Outward/"+tw.local.idcRequest.parentRequestNo+"ODC"+"/Canceled Cases";
}
